//! Actual Star Trek E–M card definitions, exercised through legal actions.
mod support;

use rustmage as _;
use rustmage_core::{cards::*, engine::*};
use support::*;

fn owned(game: &mut Game, player: Player, name: &str, zone: Zone) -> CardId {
    // TRK admission is regenerated by the set integrator after per-card proofs.
    spawn(game, player, Card::from_name(name).unwrap(), zone)
}

fn drain(game: &mut Game) {
    for _ in 0..48 {
        if game.state.pending == Pending::Priority
            && game.state.stack.is_empty()
            && game.state.pending_triggers.is_empty()
            && game.state.resolving.is_none()
        {
            return;
        }
        choose(game, |action| {
            matches!(action, Action::Pass | Action::PutTrigger { .. })
        });
    }
    panic!("resolution budget");
}

fn mana(color: usize) -> Mana {
    let mut value = [0; 6];
    value[color] = 1;
    value
}

#[test]
fn earth_and_ferenginar_enter_tapped_gain_life_and_produce_their_two_colors() {
    for (name, colors) in [("Earth, Sector 001", [1, 4]), ("Ferenginar", [2, 4])] {
        for player in [Player::P0, Player::P1] {
            for color in colors {
                let mut game = scenario(player);
                game.state.players[player.index()].mana = [0; 6];
                let land = owned(&mut game, player, name, Zone::Hand);
                act(&mut game, Action::PlayLand { card: land });
                assert!(game.object_view(land).tapped, "{name}");
                assert_eq!(game.state.players[player.index()].life, 20);
                drain(&mut game);
                assert_eq!(game.state.players[player.index()].life, 21, "{name}");
                game.untap_objects(&[land], untap_rules::UntapCause::Effect);
                act(
                    &mut game,
                    Action::ActivateMana {
                        card: land,
                        ability: 0,
                        payment: [0; 6],
                        counter_payment: Counters::default(),
                        production: mana(color),
                    },
                );
                assert_eq!(
                    game.state.players[player.index()].mana,
                    mana(color),
                    "{name}"
                );
            }
        }
    }
}

#[test]
fn eject_the_warp_core_reduces_only_its_target_and_requires_artifact_or_creature_kicker() {
    for kicked in [false, true] {
        let player = Player::P0;
        let mut game = scenario(player);
        let target = put(
            &mut game,
            player.other(),
            "Ghalta, Primal Hunger",
            Zone::Battlefield,
        );
        let artifact = put(&mut game, player, "Short Bow", Zone::Battlefield);
        let land = put(&mut game, player, "Forest", Zone::Battlefield);
        let spell = owned(&mut game, player, "Eject the Warp Core", Zone::Hand);
        let checkpoint = game.snapshot();
        let revision = game.revision();
        let index = game
            .legal_actions()
            .iter()
            .position(|action| *action == Action::AnnounceCast { card: spell })
            .unwrap();
        let mut indexed = game.clone();
        indexed.apply_index(player, revision, index).unwrap();
        act(&mut game, Action::AnnounceCast { card: spell });
        assert_eq!(game.snapshot(), indexed.snapshot());
        indexed.restore(&checkpoint).unwrap();
        assert_eq!(
            indexed.apply_index(player, revision, index),
            Err(Error::StaleRevision)
        );
        act(&mut game, Action::ChooseKicker { pay: kicked });
        act(
            &mut game,
            Action::ChooseTarget {
                target: Target::Card(target),
            },
        );
        if kicked {
            let land_ref = game.object_ref(land);
            reject(&mut game, Action::ChooseAdditionalCost { object: land_ref });
            let artifact_ref = game.object_ref(artifact);
            act(
                &mut game,
                Action::ChooseAdditionalCost {
                    object: artifact_ref,
                },
            );
        }
        pay(&mut game);
        drain(&mut game);
        assert_eq!(stats(&game, target), if kicked { (6, 6) } else { (10, 10) });
        assert_eq!(
            game.object_view(artifact).zone,
            if kicked {
                Zone::Graveyard
            } else {
                Zone::Battlefield
            }
        );
    }
}

#[test]
fn emergency_medical_hologram_targets_a_creature_then_gains_one_life() {
    for player in [Player::P0, Player::P1] {
        let mut game = scenario(player);
        let target = put(&mut game, player, "Bear Cub", Zone::Battlefield);
        let medic = owned(&mut game, player, "Emergency Medical Hologram", Zone::Hand);
        cast(&mut game, medic, None);
        for _ in 0..8 {
            if game.legal_actions().contains(&Action::ChooseTarget {
                target: Target::Card(target),
            }) {
                break;
            }
            choose(&mut game, |a| {
                matches!(a, Action::Pass | Action::PutTrigger { .. })
            });
        }
        act(
            &mut game,
            Action::ChooseTarget {
                target: Target::Card(target),
            },
        );
        drain(&mut game);
        assert_eq!(stats(&game, medic), (0, 1));
        assert_eq!(game.counter_count(target, CounterKind::PlusOne), 1);
        assert_eq!(game.state.players[player.index()].life, 21);
    }
}

#[test]
fn energize_bounces_only_opposing_creatures_and_beam_exiles_the_spell() {
    let player = Player::P0;
    let mut game = scenario(player);
    let own = put(&mut game, player, "Bear Cub", Zone::Battlefield);
    let other = put(&mut game, player.other(), "Bear Cub", Zone::Battlefield);
    let spell = owned(&mut game, player, "Energize", Zone::Hand);
    let mut invalid = game.clone();
    act(&mut invalid, Action::AnnounceCast { card: spell });
    reject(
        &mut invalid,
        Action::ChooseTarget {
            target: Target::Card(own),
        },
    );
    cast(&mut game, spell, Some(Target::Card(other)));
    drain(&mut game);
    assert_eq!(game.object_view(other).zone, Zone::Hand);
    assert_eq!(game.object_view(spell).zone, Zone::Graveyard);
    let second = put(&mut game, player.other(), "Bear Cub", Zone::Battlefield);
    let returner = game.object_ref(own);
    let action = Action::AnnounceBeamMeUp {
        card: spell,
        face: CastFace::Normal,
        cost: ManaCost {
            colored: [0, 1, 0, 0, 0, 0],
            generic: 3,
        },
        flash_surcharge: false,
        provider: None,
    };
    assert!(game.legal_actions().contains(&action));
    act(&mut game, action);
    act(
        &mut game,
        Action::ChooseTarget {
            target: Target::Card(second),
        },
    );
    act(&mut game, Action::BeginOrderedCosts);
    let clauses = game.observe(player).cast_costs.unwrap().clauses;
    let mana_clause = clauses
        .iter()
        .position(|row| !row.paid && row.clause == CastCostClause::Mana)
        .unwrap() as u16;
    act(
        &mut game,
        Action::ChooseCastCost {
            clause: mana_clause,
        },
    );
    pay(&mut game);
    let clauses = game.observe(player).cast_costs.unwrap().clauses;
    let return_clause = clauses
        .iter()
        .position(|row| !row.paid && matches!(row.clause, CastCostClause::BeamMeUpReturn(_, _)))
        .unwrap() as u16;
    act(
        &mut game,
        Action::ChooseCastCost {
            clause: return_clause,
        },
    );
    act(&mut game, Action::PayBeamMeUpReturn { object: returner });
    drain(&mut game);
    assert_eq!(game.object_view(own).zone, Zone::Hand);
    assert_eq!(game.object_view(second).zone, Zone::Hand);
    assert_eq!(game.object_view(spell).zone, Zone::Exile);
}

#[test]
fn horta_and_whales_cycle_for_basic_land_and_keep_printed_combat_keywords() {
    for (name, power, toughness, keyword) in [
        ("Horta", 7, 6, Keywords::TRAMPLE),
        ("Humpback Whales", 5, 6, Keywords::VIGILANCE),
    ] {
        let player = Player::P0;
        let mut game = scenario(player);
        let source = owned(&mut game, player, name, Zone::Hand);
        let basic = put(&mut game, player, "Island", Zone::Library);
        let nonbasic = put(&mut game, player, "Cavern of Souls", Zone::Library);
        let mut cast_branch = game.clone();
        cast(&mut cast_branch, source, None);
        drain(&mut cast_branch);
        assert_eq!(stats(&cast_branch, source), (power, toughness), "{name}");
        assert!(cast_branch.keywords(source).contains(keyword), "{name}");
        act(
            &mut game,
            Action::AnnounceActivate {
                card: source,
                ability: 0,
                counter_payment: Counters::default(),
            },
        );
        pay(&mut game);
        assert_eq!(game.object_view(source).zone, Zone::Graveyard);
        for _ in 0..8 {
            if game
                .legal_actions()
                .iter()
                .any(|a| matches!(a, Action::ChooseSearch { .. }))
            {
                break;
            }
            choose(&mut game, |a| {
                matches!(a, Action::Pass | Action::PutTrigger { .. })
            });
        }
        reject(&mut game, Action::ChooseSearch { card: nonbasic });
        act(&mut game, Action::ChooseSearch { card: basic });
        act(&mut game, Action::FinishSearch);
        drain(&mut game);
        assert_eq!(game.object_view(basic).zone, Zone::Hand);
    }
}

#[test]
fn moopsy_mugato_and_hes_dead_jim_wire_their_exact_keywords_and_spell_effects() {
    let player = Player::P0;
    let mut game = scenario(player);
    let moopsy = owned(&mut game, player, "Moopsy", Zone::Battlefield);
    let mugato = owned(&mut game, player, "Mugato", Zone::Battlefield);
    assert_eq!(stats(&game, moopsy), (1, 1));
    assert!(game.keywords(moopsy).contains(Keywords::DEATHTOUCH));
    assert!(!game.keywords(moopsy).contains(Keywords::REACH));
    assert_eq!(stats(&game, mugato), (6, 6));
    for keyword in [Keywords::REACH, Keywords::VIGILANCE, Keywords::DEATHTOUCH] {
        assert!(game.keywords(mugato).contains(keyword));
    }
    act(
        &mut game,
        Action::AnnounceActivate {
            card: moopsy,
            ability: 0,
            counter_payment: Counters::default(),
        },
    );
    pay(&mut game);
    drain(&mut game);
    assert!(game.keywords(moopsy).contains(Keywords::REACH));
    let target = put(&mut game, player.other(), "Bear Cub", Zone::Battlefield);
    let spell = owned(&mut game, player, "He's Dead, Jim", Zone::Hand);
    cast(&mut game, spell, Some(Target::Card(target)));
    for _ in 0..8 {
        if game.observe(player).library_choice.is_some() {
            break;
        }
        choose(&mut game, |a| {
            matches!(a, Action::Pass | Action::PutTrigger { .. })
        });
    }
    assert_eq!(game.object_view(target).zone, Zone::Graveyard);
    assert!(game.observe(player).library_choice.unwrap().surveil);
    choose(&mut game, |a| {
        matches!(
            a,
            Action::ArrangeLibrary {
                destination: LibraryDestination::Top,
                ..
            }
        )
    });
    drain(&mut game);
}
